def _count_pairs_sum_helper(xs: list[int], t: int) -> int:
    seen = set(xs)
    total = 0
    for x in xs:
        comp = t - x
        if comp in seen and comp != x:
            total += 1
    return total // 2


def count_pairs_sum(xs: list[int], t: int) -> int:
    """Count pairs of positions i < j with xs[i] + xs[j] == t.
pre: len(set(xs)) == len(xs)
post: __return__ >= 0
post: __return__ == sum(1 for i in range(len(xs)) for j in range(i + 1, len(xs)) if xs[i] + xs[j] == t)
post: __return__ == sum(1 for i in range(len(xs)) if (t - xs[i]) in xs and (t - xs[i]) != xs[i]) // 2"""
    return _count_pairs_sum_helper(xs, t)

