def is_prime(n: int) -> bool:
    """pre: n >= 2
post: __return__ == all(n % d != 0 for d in range(2, n))
post: __return__ == (len([d for d in range(1, n + 1) if n % d == 0]) == 2)"""
    if n == 2 or n == 3:
        return True
    if n % 2 == 0:
        return False
    d = 3
    while d * d <= n:
        if n % d == 0:
            return False
        d += 2
    return True

