def last_index_of(xs: list[int], x: int) -> int:
    """pre: x in xs
post: 0 <= __return__ < len(xs)
post: xs[__return__] == x
post: all(xs[i] != x for i in range(__return__ + 1, len(xs)))"""
    for i in range(len(xs) - 1, -1, -1):
        if xs[i] == x:
            return i
    raise ValueError("x not in xs")

