    """pre: len(xs) >= 2
post: __return__ >= 0
post: any(abs(xs[i + 1] - xs[i]) == __return__ for i in range(len(xs) - 1))
post: all(abs(xs[i + 1] - xs[i]) <= __return__ for i in range(len(xs) - 1))"""
    return max(abs(xs[i + 1] - xs[i]) for i in range(len(xs) - 1))

