def median_odd(xs: list[int]) -> int:
    """Return the median of xs: the element that would be in the middle if xs were sorted.
pre: len(xs) % 2 == 1
pre: len(set(xs)) == len(xs)
post: __return__ in xs
post: sum(1 for x in xs if x < __return__) == len(xs) // 2
post: sum(1 for x in xs if x > __return__) == len(xs) // 2"""
    return _sorted_middle(xs)

